action.mutation:
mutation CreateShift($payload: [ShiftCreatePayloadInput!]!) {
  mutation: createShift(payload: $payload) { 
    id
    name
  }
}

mutation UpdateShift($payload: [ShiftUpdatePayloadInput!]!) {
  mutation: updateShift(payload: $payload) { 
    id
    name
  }
}

mutation DeleteShift($payload: [ShiftDeletePayloadInput!]!) {
  mutation: deleteShift(payload: $payload) { 
    id
    name
  }
}
